/**
 * How a stored credential is materialized into HTTP request shape when the
 * proxy forwards a request upstream.
 */
export type ProxyCredentialTemplate = {
    /**
     * Header name (`Authorization`, `x-api-key`, `x-goog-api-key`, …).
     */
    key: string;
    kind: 'header';
    /**
     * Optional prefix prepended to the credential value
     * (e.g. `"Bearer "` for `Authorization: Bearer sk-…`). `None`
     * inserts the secret verbatim.
     */
    prefix_value?: string | null;
} | {
    kind: 'basic_auth';
    /**
     * Username paired with the stored secret as the password.
     */
    username: string;
} | {
    /**
     * Cookie name; the value is the credential secret.
     */
    key: string;
    kind: 'cookie';
} | {
    /**
     * Query-parameter name; the value is the credential secret.
     */
    key: string;
    kind: 'query_param';
};

